-- zetaris/20_dq.sql · Data-quality views (spec E5, WS1-14). Owner: nexus-2 (engines lane).
-- GENERATED by `python -m app.adapters.dq_rules` from services/api/app/adapters/dq_rules.py, the same
-- rule text the q_dq_flags DuckDB twin runs. Do not edit by hand; tests/engines/test_dq.py checks it.
-- One statement per call; register.py strips the trailing semicolons and fills {{city:...}} from
-- cities/<city>/city.yaml. Views live in schema-store container `nexus` (queried as nexus.<view>).

CREATE OR REPLACE SCHEMASTORE VIEW dq_duplicate_firs WITH CONTAINER nexus AS
SELECT a.crime_id AS crime_id, 'duplicate_fir' AS rule, b.crime_id AS other_id, concat('same ', a.category, ' within ', CAST(CAST(abs(unix_timestamp(a.occurred_from) - unix_timestamp(b.occurred_from)) / 60 AS INT) AS STRING), ' min and ', CAST(CAST(greatest(abs(a.lat - b.lat), abs(a.lon - b.lon)) * 111000 AS INT) AS STRING), ' m, filed at ', coalesce(b.station_id, '?'), ' via ', b.source) AS detail FROM nexus.v_crime_unified a JOIN nexus.v_crime_unified b ON a.category = b.category AND a.crime_id <> b.crime_id AND abs(unix_timestamp(a.occurred_from) - unix_timestamp(b.occurred_from)) <= 1800 AND abs(a.lat - b.lat) <= 0.0025 AND abs(a.lon - b.lon) <= 0.0025 AND (coalesce(a.station_id, '') <> coalesce(b.station_id, '') OR a.source <> b.source);

CREATE OR REPLACE SCHEMASTORE VIEW dq_bad_geo WITH CONTAINER nexus AS
SELECT crime_id, 'bad_geo' AS rule, CAST(NULL AS STRING) AS other_id, CASE WHEN lat IS NULL OR lon IS NULL THEN 'no coordinates' ELSE concat('outside city bounds: ', CAST(lat AS STRING), ', ', CAST(lon AS STRING)) END AS detail FROM nexus.v_crime_unified WHERE lat IS NULL OR lon IS NULL OR lon < {{city:map.bounds.0}} OR lon > {{city:map.bounds.2}} OR lat < {{city:map.bounds.1}} OR lat > {{city:map.bounds.3}};

CREATE OR REPLACE SCHEMASTORE VIEW dq_time_inconsistent WITH CONTAINER nexus AS
SELECT crime_id, 'time_inconsistent' AS rule, CAST(NULL AS STRING) AS other_id, CASE WHEN occurred_from > reported_at THEN 'occurred after it was reported' ELSE 'occurrence ends before it starts' END AS detail FROM nexus.v_crime_unified WHERE occurred_from > reported_at OR occurred_to < occurred_from;

CREATE OR REPLACE SCHEMASTORE VIEW dq_unmapped_sections WITH CONTAINER nexus AS
SELECT crime_id, 'unmapped_section' AS rule, CAST(NULL AS STRING) AS other_id, concat('legacy sections not mapped: ', sections_raw) AS detail FROM nexus.v_crime_unified WHERE sections_raw IS NOT NULL;

CREATE OR REPLACE SCHEMASTORE VIEW dq_flags WITH CONTAINER nexus AS
SELECT a.crime_id AS crime_id, 'duplicate_fir' AS rule, b.crime_id AS other_id, concat('same ', a.category, ' within ', CAST(CAST(abs(unix_timestamp(a.occurred_from) - unix_timestamp(b.occurred_from)) / 60 AS INT) AS STRING), ' min and ', CAST(CAST(greatest(abs(a.lat - b.lat), abs(a.lon - b.lon)) * 111000 AS INT) AS STRING), ' m, filed at ', coalesce(b.station_id, '?'), ' via ', b.source) AS detail FROM nexus.v_crime_unified a JOIN nexus.v_crime_unified b ON a.category = b.category AND a.crime_id <> b.crime_id AND abs(unix_timestamp(a.occurred_from) - unix_timestamp(b.occurred_from)) <= 1800 AND abs(a.lat - b.lat) <= 0.0025 AND abs(a.lon - b.lon) <= 0.0025 AND (coalesce(a.station_id, '') <> coalesce(b.station_id, '') OR a.source <> b.source) UNION ALL SELECT crime_id, 'bad_geo' AS rule, CAST(NULL AS STRING) AS other_id, CASE WHEN lat IS NULL OR lon IS NULL THEN 'no coordinates' ELSE concat('outside city bounds: ', CAST(lat AS STRING), ', ', CAST(lon AS STRING)) END AS detail FROM nexus.v_crime_unified WHERE lat IS NULL OR lon IS NULL OR lon < {{city:map.bounds.0}} OR lon > {{city:map.bounds.2}} OR lat < {{city:map.bounds.1}} OR lat > {{city:map.bounds.3}} UNION ALL SELECT crime_id, 'time_inconsistent' AS rule, CAST(NULL AS STRING) AS other_id, CASE WHEN occurred_from > reported_at THEN 'occurred after it was reported' ELSE 'occurrence ends before it starts' END AS detail FROM nexus.v_crime_unified WHERE occurred_from > reported_at OR occurred_to < occurred_from UNION ALL SELECT crime_id, 'unmapped_section' AS rule, CAST(NULL AS STRING) AS other_id, concat('legacy sections not mapped: ', sections_raw) AS detail FROM nexus.v_crime_unified WHERE sections_raw IS NOT NULL;

CREATE OR REPLACE SCHEMASTORE VIEW dq_orphan_evidence WITH CONTAINER nexus AS
SELECT e.evidence_id, e.crime_id, 'evidence for a crime missing from v_crime_unified' AS detail FROM sb.evidence_media e LEFT JOIN nexus.v_crime_unified c ON c.crime_id = e.crime_id WHERE c.crime_id IS NULL;

CREATE OR REPLACE SCHEMASTORE VIEW dq_tip_without_incident WITH CONTAINER nexus AS
SELECT t.tip_id, t.category, t.received_week, 'tip not tied to a public incident' AS detail FROM sb.tips_v t WHERE t.public_incident_id IS NULL AND t.status NOT IN ('quarantined', 'closed');

CREATE OR REPLACE SCHEMASTORE VIEW dq_stale_cameras WITH CONTAINER nexus AS
SELECT camera_id, owner_type, contact_station, last_updated, concat('camera registry not updated for ', CAST(datediff(current_date(), CAST(last_updated AS DATE)) AS STRING), ' days') AS detail FROM s3csv.cctv_cameras WHERE datediff(current_date(), CAST(last_updated AS DATE)) > 180;
